on conflict (item_no, screen_id, row_label, price_col) do nothing;
insert into public.catalog_item_numbers (item_no, screen_id, row_label, price_col, dl_description)
select r->>'Part #', c.id, r->>'Description', 'Price/Box', r->>'Description'
from public.pricing_catalog c, jsonb_array_elements(c.data->'rows') r
where c.id = 'duro_last:fasteners_and_bits' and coalesce(r->>'Part #', '') not in ('', '0') and (r->>'Description' like 'Duro-Tech TPO %' or r->>'Description' like 'Drain Guard Clamping Ring%')
on conflict (item_no, screen_id, row_label, price_col) do nothing;
-- 8b. Pipe stacks: open and closed part numbers → Price
insert into public.catalog_item_numbers (item_no, screen_id, row_label, price_col, dl_description)
select r->>k, c.id, r->>'Description', 'Price', r->>'Description'
from public.pricing_catalog c, jsonb_array_elements(c.data->'rows') r, unnest(array['Open Part #','Closed Part #']) k
where c.id = 'non_dl_tpo:pipe_stacks' and coalesce(r->>k, '') not in ('', '0') and true
on conflict (item_no, screen_id, row_label, price_col) do nothing;
insert into public.catalog_item_numbers (item_no, screen_id, row_label, price_col, dl_description)
select r->>k, c.id, r->>'Description', 'Price', r->>'Description'
from public.pricing_catalog c, jsonb_array_elements(c.data->'rows') r, unnest(array['Open Part #','Closed Part #']) k
where c.id = 'epdm:pipe_stacks' and coalesce(r->>k, '') not in ('', '0') and true
on conflict (item_no, screen_id, row_label, price_col) do nothing;
insert into public.catalog_item_numbers (item_no, screen_id, row_label, price_col, dl_description)
